#include "cfss/backtest.hpp"
#include <iostream>
#include <stdexcept>
using namespace cfss::backtest;
static void require(bool ok,const char* msg){if(!ok)throw std::runtime_error(msg);}
int main(){
 try{
  Input x{};x.dataset_id="synthetic-fixture-not-market-evidence";x.risk_fraction=0.01;x.costs={0.0004,0.0004,0.0002,0.0002,0.0001};
  const std::int64_t t0=1735689600000LL;std::vector<Bar> b;
  for(int i=0;i<280;++i)b.push_back({t0+std::int64_t(i)*86400000LL,100,100.5,99.5,100});
  b[182].high=111;b[182].close=110;b[202].high=111;b[202].low=94;
  x.bars["BTC-USDT-SWAP"]=b;
  x.candidates.push_back({"lrt-001","PLAN_A_LRT","BTC-USDT-SWAP","LONG",std::string(64,'a'),"PROXY",t0+181LL*86400000LL,t0+100LL*86400000LL,100,95,110,3});
  x.candidates.push_back({"nmt-001","PLAN_A_NMT","BTC-USDT-SWAP","LONG",std::string(64,'b'),"PROXY",t0+201LL*86400000LL,t0+120LL*86400000LL,100,95,110,3});
  x.candidates.push_back({"nmt-overlap-censored","PLAN_A_NMT","BTC-USDT-SWAP","LONG",std::string(64,'c'),"PROXY",t0+230LL*86400000LL,t0+100LL*86400000LL,100,95,110,30});
  b[245].high=111; b[245].close=110;
  Input short_data{}; short_data.dataset_id="short-history-censor-fixture"; short_data.risk_fraction=0.01; short_data.costs=x.costs; short_data.bars["BTC-USDT-SWAP"]={{t0,100,100.5,99.5,100},{t0+86400000LL,100,100.5,99.5,100}}; Candidate short_candidate{"short-history","PLAN_A_LRT","BTC-USDT-SWAP","LONG",std::string(64,'d'),"PROXY",t0,t0,100,95,110,3}; auto censored_short=simulate(short_data,short_candidate,t0+10LL*86400000LL); require(!censored_short.has_value(),"insufficient end-of-data bars censor trade instead of shortening holding period");
  Input gap_data{}; gap_data.dataset_id="gap-fill-risk-normalization-fixture"; gap_data.risk_fraction=0.01; gap_data.costs=x.costs; gap_data.bars["BTC-USDT-SWAP"]={{t0,100,100.5,99.5,100},{t0+86400000LL,110,111,109,110},{t0+2LL*86400000LL,120,121,119,120}}; Candidate gap_candidate{"gap-fill","PLAN_A_LRT","BTC-USDT-SWAP","LONG",std::string(64,'e'),"PROXY",t0,t0,100,95,120,2}; require(gap_candidate.data_class=="PROXY","synthetic gap fixture must not claim REAL provenance"); auto gap_trade=simulate(gap_data,gap_candidate,t0+10LL*86400000LL); require(gap_trade.has_value(),"gap-fill candidate executes in fixture"); const double gap_fill=110*(1+x.costs.entry_slippage),gap_exit=120*(1-x.costs.exit_slippage); const double expected_gross_r=(gap_exit-gap_fill)/(gap_fill-95); require(std::abs(gap_trade->gross_r-expected_gross_r)<1e-9,"R multiple uses actual gap-adjusted fill-to-stop risk");
  const auto r=run(x);require(!r.folds.empty(),"walk-forward folds");require(r.lrt.trades==1,"LRT isolation");require(r.nmt.trades==1,"NMT isolation");require(r.nmt.censored==1,"unique OOS candidate censored in its first eligible fold is not promoted from a later overlapping fold");
  require(r.lrt.wins==1,"target is win");require(r.nmt.losses==1,"ambiguous bar stop-first");
  auto invalid_risk=x; invalid_risk.risk_fraction=1.01; bool risk_rejected=false; try{run(invalid_risk);}catch(const std::invalid_argument&){risk_rejected=true;}require(risk_rejected,"risk fraction above 100% is rejected");
  auto bad_hash=x; bad_hash.candidates[0].parameter_hash=std::string(63,'a')+"z"; bool hash_rejected=false; try{run(bad_hash);}catch(const std::invalid_argument&){hash_rejected=true;}require(hash_rejected,"parameter hash must be 64 lowercase hexadecimal characters");
  auto bad_slippage=x; bad_slippage.costs.entry_slippage=1.0; bool slip_rejected=false; try{run(bad_slippage);}catch(const std::invalid_argument&){slip_rejected=true;}require(slip_rejected,"slippage >= 100% rejected to prevent invalid fill math");
  Input entry_gap_data{}; entry_gap_data.dataset_id="entry-gap-invalid-fixture"; entry_gap_data.risk_fraction=0.01; entry_gap_data.costs=x.costs; entry_gap_data.bars["BTC-USDT-SWAP"]={{t0,90,91,88,89},{t0+86400000LL,90,91,88,89}}; Candidate entry_gap_candidate{"entry-gap-invalid","PLAN_A_LRT","BTC-USDT-SWAP","LONG",std::string(64,'1'),"PROXY",t0-1,t0-1,100,95,110,2}; require(!simulate(entry_gap_data,entry_gap_candidate,t0+10LL*86400000LL).has_value(),"entry fill already beyond stop must be rejected, not counted as stop-gap loss");
  Input target_gap_data{}; target_gap_data.dataset_id="entry-gap-target-invalid-fixture"; target_gap_data.risk_fraction=0.01; target_gap_data.costs=x.costs; target_gap_data.bars["BTC-USDT-SWAP"]={{t0,111,112,110,111},{t0+86400000LL,111,112,110,111}}; Candidate target_gap_candidate{"entry-gap-target-invalid","PLAN_A_LRT","BTC-USDT-SWAP","LONG",std::string(64,'2'),"PROXY",t0-1,t0-1,100,95,110,2}; require(!simulate(target_gap_data,target_gap_candidate,t0+10LL*86400000LL).has_value(),"entry fill already beyond target must not be credited as a target exit");
  Input stop_gap_data2{}; stop_gap_data2.dataset_id="stop-gap-fill-realistic-fixture"; stop_gap_data2.risk_fraction=0.01; stop_gap_data2.costs=x.costs; stop_gap_data2.bars["BTC-USDT-SWAP"]={{t0,100,101,99,100},{t0+86400000LL,90,91,88,89}}; Candidate stop_gap_candidate2{"stop-gap","PLAN_A_LRT","BTC-USDT-SWAP","LONG",std::string(64,'f'),"PROXY",t0-1,t0-1,100,95,110,2}; auto stop_gap_trade2=simulate(stop_gap_data2,stop_gap_candidate2,t0+10LL*86400000LL); require(stop_gap_trade2.has_value(),"gap stop fixture executes"); require(stop_gap_trade2->outcome=="STOP_GAP","stop crossed by opening gap must be flagged");
  const double entry_fill2=100*(1+x.costs.entry_slippage),exit_fill2=90*(1-x.costs.exit_slippage); const double gross_gap2=(exit_fill2-entry_fill2)/entry_fill2; const double funding2=3*x.costs.funding_per_8h; const double net_gap2=(gross_gap2-x.costs.entry_fee-x.costs.exit_fee-funding2)/(std::abs(entry_fill2-95)/entry_fill2); require(std::abs(stop_gap_trade2->net_r-net_gap2)<1e-9,"gap stop uses adverse opening price, entry fill risk, and holding-period funding");
  const auto j=to_json(r);require(r.data_class=="PROXY_CANDIDATES","synthetic fixtures must never be labeled REAL");require(j["data_class"]=="PROXY_CANDIDATES","report preserves proxy-only synthetic fixture classification");require(j["baselines"]["status"]=="UNAVAILABLE","no fabricated baselines"); require(j["lrt_unique_oos"]["max_drawdown_pct"].is_null()&&j["nmt_unique_oos"]["max_drawdown_pct"].is_null(),"portfolio drawdown stays unavailable without concurrent exposure and mark-to-market ledger"); require(j["lrt_unique_oos"]["sharpe_oos"].is_null()&&j["nmt_unique_oos"]["sharpe_oos"].is_null(),"portfolio Sharpe stays unavailable without daily portfolio equity returns"); require(std::find(j["limitations"].begin(),j["limitations"].end(),"Portfolio drawdown and Sharpe are UNAVAILABLE: v1 has no event-driven concurrent-position, capital-allocation, or mark-to-market ledger")!=j["limitations"].end(),"report discloses portfolio metric limitation"); require(std::find(j["limitations"].begin(),j["limitations"].end(),"Risk fraction is validated as an input but is not applied to portfolio sizing or equity because v1 has no portfolio ledger")!=j["limitations"].end(),"report discloses validated but unapplied portfolio risk fraction");
  require(j["gate_status"]=="NOT_EVALUATED_INCOMPLETE_EVIDENCE","fixture cannot pass Gate A"); require(j["walk_forward"]["training_used"]==false,"fixed candidates are not fitted on a training window"); require(j["walk_forward"]["methodology"]=="FIXED_PREREGISTERED_CANDIDATE_ROLLING_OOS","methodology must not claim model training");
  require(!j["actionable"].get<bool>()&&!j["trade_execution_allowed"].get<bool>(),"manual only");
  std::cout<<"STAGE8_PLAN_A_BACKTEST_TESTS_PASS\n";return 0;
 }catch(const std::exception& e){std::cerr<<"STAGE8_PLAN_A_BACKTEST_TESTS_FAIL: "<<e.what()<<'\n';return 1;}
}